def finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary, KINDS[(ordinal + 8) % len(KINDS)], KINDS[(ordinal + 17) % len(KINDS)]]
    return {"id": fid, "name": name,
            "description": f"Records {low} as source-qualified Debt Instrument context while party, document, issuance, holding, payment, ledger, market, valuation, rating, collateral, guarantee, default, dispute, enforcement, insolvency, tax, filing and records masters remain external.",
            "source_refs": refs,
            "questions": [
                {"id": f"{fid}-q01", "text": f"Which stable instrument, version, contractual basis, debt class, jurisdiction and master-system identities establish {low}?", "kind": kinds[0], "answer_data": ["instrument and version identifiers, namespace, predecessor and successor", "debt form, class, governing basis, jurisdiction and authoritative master", "source, status, effective interval, event time and knowledge time"]},
                {"id": f"{fid}-q02", "text": f"Who issued, owes, holds rights in, services, validates, changes or may access {low}, under what authority and role?", "kind": kinds[1], "answer_data": ["issuer, borrower, obligor, creditor, lender, investor, trustee, agent, calculation agent and guarantor roles", "agreement, mandate, policy, approval, access purpose and delegated authority", "assertion owner, reviewer, steward, dispute state and applicable restriction"]},
                {"id": f"{fid}-q03", "text": f"Which amount, currency, rate, schedule, condition, event, observation, evidence, uncertainty and lineage qualify {low}?", "kind": kinds[2], "answer_data": ["principal, notional, outstanding amount, currency, rate, index, spread, fee and formula", "issue, accrual, reset, due, exercise, maturity, observation and knowledge times", "source document, evidence digest, confidence, contradiction, external outcome and semantic-loss declaration"]}],
            "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed values and references needed to answer the governed questions for {low} without copying external master lifecycles.", "value_kind": "object", "cardinality": "1", "required": True, "source_refs": refs}],
            "artifacts": [{"id": f"{fid}-artifact", "name": f"{name} evidence manifest", "description": f"Digest-addressed manifest for authoritative terms, schedules, assertions, mappings and external references supporting {low}.", "media_or_form": ["application/json", "application/yaml", "text/markdown", "external reference"], "serial": True, "identity_strategy": "Authoritative master-system identifier first, otherwise governed IRI, then Dimension UUID or ULID; include immutable revision and digest.", "source_refs": refs}],
            "inline_only_rationale": None}


def structure():
    out, ordinal = [], 0
    for bid, bname, rationale, layers in ROWS:
        built_layers, bundle_refs = [], []
        for lid, lname, refs, items in layers:
            bundle_refs.extend(refs)
            built = []
            for item in items:
                ordinal += 1
                built.append(finding(item, ordinal, refs))
            built_layers.append({"id": lid, "name": lname, "description": f"Groups governed findings for {lname.lower()} while preserving debt-instrument boundary and source authority.", "source_refs": refs, "findings": built})
        out.append({"id": bid, "name": bname, "description": rationale, "rationale": rationale, "source_refs": list(dict.fromkeys(bundle_refs)), "layers": built_layers})
    return {"bundles": out}


